        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change #4: EF 9 uses sync-over-async for Cosmos which may deadlock.
        // Use async methods instead.
        RunAsync(context).GetAwaiter().GetResult();
    }

    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();

        // Breaking change #5: Raw SQL queries referencing "Discriminator" must be
        // updated if you did NOT apply the HasJsonPropertyName("Discriminator") fix.
        // With the fix in BlogContext, this query still works as-is:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // Without the fix you'd need:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    }
}

